from collections import deque

waiting = deque([{'id': 'd-1', 'attempts': 0}, {'id': 'd-2', 'attempts': 0}])
completed, dead_letters = set(), []
while waiting:
    job = waiting.popleft()
    if job['id'] in completed:
        continue
    try:
        if job['id'] == 'd-2':
            raise ValueError('unknown course')
        completed.add(job['id'])
    except ValueError as error:
        job['attempts'] += 1
        if job['attempts'] >= 2:
            dead_letters.append({'id': job['id'], 'reason': str(error)})
        else:
            waiting.append(job)
assert completed == {'d-1'}
assert dead_letters == [{'id': 'd-2', 'reason': 'unknown course'}]
print(sorted(completed), dead_letters)
